<set-variable name="promptText" value="@{
    var reqBody = context.Request.Body.As(preserveContent: true);
    var messages = (JArray)reqBody["messages"];
    var lastUserMessage = "";
    foreach (var m in messages) {
        if ((string)m["role"] == "user") {
            lastUserMessage = (string)m["content"];
        }
    }
    return lastUserMessage;
}" />

  https://prompt-governance-functions.azurewebsites.net/api/classification?code={{classification-function-key}}
  POST

    application/json

  @{
      return new JObject(new JProperty("prompt", (string)context.Variables["promptText"])).ToString();
  }

<set-variable name="classificationResult" value="@(((IResponse)context.Variables["classificationResponse"]).Body.As(preserveContent: true))" />



      https://prompt-governance-functions.azurewebsites.net/api/log_writer?code={{logwriter-function-key}}
      POST

        application/json

      @{
          var classification = (JObject)context.Variables["classificationResult"];
          var payload = new JObject(
              new JProperty("prompt", (string)context.Variables["promptText"]),
              new JProperty("response", ""),
              new JProperty("classification", classification["classification"]),
              new JProperty("action", classification["action"].ToString()),
              new JProperty("triggered_rule", classification["triggered_rule"]),
              new JProperty("model", "gpt-4o-mini"),
              new JProperty("prompt_tokens", 0),
              new JProperty("completion_tokens", 0),
              new JProperty("latency_ms", 0)
          );
          return payload.ToString();
      }



      @(((JObject)context.Variables["classificationResult"]).ToString())




  @("Bearer {{openai-api-key}}")


  identity
